<?php
require_once dirname(__DIR__).'/app/bootstrap.php';$today=date('Y-m-d H:i:s');$s=db()->prepare("SELECT * FROM events WHERE status='published' AND (ends_at='' OR ends_at>=:today) ORDER BY starts_at ASC LIMIT 60");$s->execute([':today'=>$today]);$events=$s->fetchAll();$pageTitle='Local events | '.setting('site_name','MetroGuide');$pageDescription='Discover events, workshops and activities around your neighbourhood.';include __DIR__.'/includes/header.php';?>
<main id="main" class="container account-page"><div class="page-intro"><span class="eyebrow">WHAT'S HAPPENING LOCALLY</span><h1>Good things are happening nearby.</h1><p>Community events, workshops, meetups and local experiences submitted by organisers and reviewed by the guide team.</p></div><?php if($events): ?><div class="event-grid"><?php foreach($events as $e): ?><article class="event-card"><div class="event-date"><strong><?= h(date('d',strtotime($e['starts_at']))) ?></strong><span><?= h(date('M',strtotime($e['starts_at']))) ?></span></div><div class="event-content"><span class="eyebrow"><?= h($e['location']?:'Local event') ?></span><h2><?= h($e['title']) ?></h2><p><?= h(text_excerpt($e['description'],180)) ?></p><div class="event-meta"><span><i class="fa-regular fa-clock"></i> <?= h(date('M j, Y · g:i A',strtotime($e['starts_at']))) ?></span><?php if($e['venue']): ?><span><i class="fa-solid fa-location-dot"></i> <?= h($e['venue']) ?></span><?php endif; ?></div><?php if($e['organizer_url']): ?><a class="text-link" href="<?= h($e['organizer_url']) ?>" target="_blank" rel="noopener">Event details <i class="fa-solid fa-arrow-up-right-from-square"></i></a><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span><i class="fa-regular fa-calendar"></i></span><h3>No upcoming events listed yet</h3><p>Local organisers and business owners can submit an event for review.</p><a class="button button-primary" href="<?= app_path('auth.php?mode=register') ?>">Join to submit an event</a></div><?php endif; ?></main><?php include __DIR__.'/includes/footer.php';?>
